commands:
printf "const rateLimit = require("express-rate-limit");
module.exports = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  keyGenerator: (req) => req.ip,
  handler: (req, res) => res.status(429).json({error: "Too Many Requests"}),
  standardHeaders: true,
  legacyHeaders: false
});" > rate-limiter.js

examples:
printf "const rateLimit = require("express-rate-limit");
module.exports = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  keyGenerator: (req) => req.headers["x-api-key"] || req.ip,
  handler: (req, res) => res.status(429).json({error: "Too Many Requests"}),
  standardHeaders: true,
  legacyHeaders: false
});" > rate-limiter.js

commands:
printf "async function rateLimitPlugin(fastify) {
  await fastify.register(require("@fastify/rate-limit"), {
    max: 100,
    timeWindow: "1 minute",
    keyGenerator: (req) => req.headers["x-api-key"] || req.ip,
    redis: fastify.redis
  });
}
module.exports = rateLimitPlugin;" > rate-limit.js

